document.head.insertAdjacentHTML("beforeend", "<link rel=\"stylesheet\" href=\"https://testingcf.jsdelivr.net/npm/@fontsource/noto-serif-sc@5.3.1/400.css\">\n<link rel=\"stylesheet\" href=\"https://testingcf.jsdelivr.net/npm/@fontsource/noto-serif-sc@5.3.1/700.css\">\n<link rel=\"stylesheet\" href=\"https://testingcf.jsdelivr.net/npm/@fontsource/fraunces@5.3.0/900.css\">\n<link rel=\"stylesheet\" href=\"https://testingcf.jsdelivr.net/npm/@fontsource/dm-serif-display@5.3.0/400.css\">");
document.body.insertAdjacentHTML("afterbegin", "<div id=\"intro\">\n<div class=\"cover\"><img src=\"https://testingcf.jsdelivr.net/gh/abcxyzeric/card108@main/assets/intro-cover.webp\" alt=\"\"><div class=\"title\"><span>MIDSOMMAR</span>Đêm Giữa Hạ</div></div>\n<div class=\"seam\"></div>\n<div class=\"main\">\n<div class=\"lead\"><p>Mùa tốt nghiệp, bạn cùng bạn gái Lạc Cẩn và cô bạn học Chúc Lẫm, theo chân cô bạn thân người Thụy Điển Linnea bay đến Hälsingland thuộc miền trung Thụy Điển.</p><p>Nằm sâu trong thung lũng, ngôi làng Hårga năm nay vào tiết Hạ chí đúng dịp diễn ra đại lễ chín mươi năm một lần. Hiện tượng ban ngày vùng cực nơi đây khiến mặt trời không bao giờ lặn, dân làng đều thay sang những bộ váy áo vải lanh trắng tự tay dệt, cùng nhau khiêu vũ quanh cột Tháng Năm.</p><p>Chỉ là bạn vẫn chưa nhận ra rằng, chuyến đi này ngay từ đầu đã không đơn thuần là làm khách — Linnea cùng các cô gái trong làng đang tính toán giữ bạn ở lại Hårga mãi mãi. Thuận theo sự níu giữ của họ, hay dắt theo người bên cạnh cùng rời đi? Từng bước đi tiếp theo như thế nào, hoàn toàn do bạn quyết định.</p></div>\n<div class=\"pv\"><video controls playsinline preload=\"none\" poster=\"https://testingcf.jsdelivr.net/gh/abcxyzeric/card108@main/assets/pv-poster.webp\"><source src=\"https://testingcf.jsdelivr.net/gh/abcxyzeric/card108@main/assets/pv.webm\" type='video/webm; codecs=\"av01.0.08M.10, opus\"'><source src=\"https://testingcf.jsdelivr.net/gh/abcxyzeric/card108@main/assets/pv.mp4\" type=\"video/mp4\"></video></div>\n<h2>Hướng dẫn cách chơi</h2>\n<div class=\"grid g2\">\n<div class=\"cell\" style=\"--c:#B88A0F\"><span class=\"t\">Trải nghiệm cốt truyện</span>Dưới lịch trình mười ngày được thiết kế tỉ mỉ, lễ hội của Hårga kéo dài từ sáng sớm cho đến màn đêm không bao giờ tắt. Mỗi một buổi đều có tiết mục mới chờ bạn tham gia.</div>\n<div class=\"cell\" style=\"--c:#D8452F\"><span class=\"t\">Khám phá khung cảnh</span>Trải qua khúc dạo đầu gồm Sân bay, Trên đường và Bãi cỏ ngoài làng, bạn có thể tự do di chuyển giữa 17 địa điểm trong làng, toàn bộ đều được trang bị hình minh họa độc lập.</div>\n<div class=\"cell\" style=\"--c:#E48AA3\"><span class=\"t\">Phát triển mối quan hệ</span>Năm nhân vật nữ chính, năm nỗi niềm tâm sự. Kề vai bên họ qua từng thời khắc của lễ hội, từng lời nói cử chỉ của bạn đều sẽ thay đổi ánh mắt họ nhìn bạn.</div>\n<div class=\"cell\" style=\"--c:#3F6FB5\"><span class=\"t\">Kết cục của bạn</span>Khi chín ngày đại lễ dần khép lại, ở lại hay rời đi hoàn toàn do bạn lựa chọn. Ở lại Hårga, hay bước lên con đường trở về, lựa chọn của bạn sẽ dẫn tới kết cục ra sao?</div>\n</div>\n<div class=\"go\"><button id=\"go\">Lên đường ngay</button></div>\n<p class=\"credit\">Tạo card: ssd (@buyssdcom)<span>Việt hóa: card108</span></p>\n</div>\n</div>\n<style>\n*{box-sizing:border-box;margin:0;padding:0}\nhtml,body{overflow:hidden}\nbody{font-family:\"Noto Serif SC\",\"Source Han Serif SC\",\"Songti SC\",\"STSong\",\"SimSun\",serif;font-size:14px;line-height:1.7;color:#27302A;background:transparent}\n#intro{background:#FBFAF6;border:1px solid #E2DFD3;border-radius:12px;overflow:hidden}\n.cover{position:relative;aspect-ratio:3/2}\n.cover img{display:block;width:100%;height:100%;object-fit:cover}\n.cover::after{content:\"\";position:absolute;inset:55% 0 0;background:linear-gradient(transparent,rgba(20,24,18,.62))}\n.title{position:absolute;left:0;right:0;bottom:6%;z-index:1;text-align:center;font-size:40px;font-weight:700;letter-spacing:.32em;text-indent:.32em;line-height:1.2;color:#fff;text-shadow:0 2px 14px rgba(0,0,0,.45)}\n.title span{display:block;margin-bottom:4px;font-size:11px;font-weight:400;letter-spacing:.6em;text-indent:.6em;opacity:.85}\n.pv{margin-top:16px;aspect-ratio:16/9;background:#000;border-radius:8px;overflow:hidden}\n.pv video{display:block;width:100%;height:100%}\n.seam{height:4px;background:linear-gradient(90deg,#5E7E44,#E8B923,#D8452F,#E48AA3,#8A6CB4,#3F6FB5)}\n.main{padding:16px 18px 18px}\n.lead{position:relative;margin:6px 0 0 14px;padding-left:22px;border-left:1px solid color-mix(in srgb,#5E7E44 45%,transparent);font-size:16px;line-height:2;text-align:justify}\n.lead::before{content:\"\\201C\";position:absolute;left:-19px;top:-10px;width:36px;height:32px;background:#FBFAF6;text-align:center;font:900 46px/1 \"Fraunces\",serif;color:#5E7E44}\n.lead p+p{margin-top:6px}\nh2{margin:22px 0 10px;font-size:17px;letter-spacing:.14em}\n.grid{display:grid;gap:8px;counter-reset:n}\n.g2{grid-template-columns:repeat(2,1fr)}\n.cell{position:relative;counter-increment:n;padding:10px 12px 11px;border:1px solid #E2DFD3;border-radius:8px;background:#FFFFFF;font-size:15px;line-height:1.9}\n.cell::after{content:counter(n,decimal-leading-zero);position:absolute;right:14px;top:6px;font:400 32px/1 \"DM Serif Display\",serif;color:color-mix(in srgb,var(--c) 28%,transparent)}\n.cell .t{display:block;margin-bottom:3px;font-size:15px;font-weight:700;letter-spacing:.1em;color:var(--c)}\n.go{display:flex;flex-direction:column;align-items:center;gap:8px;margin-top:18px}\n#go{padding:9px 44px;border:0;border-radius:8px;background:#5E7E44;font:inherit;font-size:16px;letter-spacing:.3em;text-indent:.3em;color:#fff;cursor:pointer;transition:filter .15s}\n#go:hover{filter:brightness(1.1)}\n.credit{margin-top:14px;font-size:11.5px;letter-spacing:.06em;text-align:center;color:#6B7166}\n.credit span{margin-left:1.5em}\n@media (max-width:520px){.main{padding:14px 12px 16px}.lead{font-size:15px;line-height:1.95}.title{font-size:30px}.cell,.cell .t{font-size:14px}}\n</style>");
document.getElementById('go').addEventListener('click', () => {
  const btn = document.querySelector('.mes[mesid="0"] .swipe_right') || document.querySelector('.swipe_right');
  if (btn) {
    btn.click();
  } else {
    try {
      if (typeof triggerSlash === 'function') triggerSlash('/swipe');
    } catch (e) {}
  }
});
